            {
                "roomNumber": 101,
                "guestName": "João Silva",
                "guestEmail": "joao@example.com",
                "guestCpf": "123.456.789-00",
                "checkIn": "2027-03-10",
                "checkOut": "2027-03-12",
                "guests": 2,
                "ratePlan": "STANDARD"
            }
