    }

    @Test
    @Order(11)
    void shouldRejectCapacityExceeded() throws Exception {
        String request = """
            {
                "roomNumber": 101,
                "guestName": "Too Many",
                "guestEmail": "toomany@example.com",
                "guestCpf": "000.000.000-00",
                "checkIn": "2027-05-10",
                "checkOut": "2027-05-12",
                "guests": 3,
                "ratePlan": "STANDARD"
            }
        """;

        HttpResponse<String> response = post("/reservations", request);

